import { ActionDefinition } from '../../../Action'
import {
    TableNameColumn,
    ConditionsColumn,
    ChoiceColumn,
    FieldNameColumn,
    BooleanColumn,
    IntegerColumn,
    StringColumn,
    TemplateValueColumn,
} from '../../../../db'

export const updateMultipleRecords = ActionDefinition({
    $id: '9daf2a72c75100105312134c95c26073',
    name: 'Update Multiple Records',
    description: `<p>Update Multiple Records on a ServiceNow table. You can configure the conditions for the records to be updated. Server-side validation rules are enforced (data policy, business rules, dictionary-defined mandatory fields), but UI policy does not apply.
</p>`,
    inputs: {
        table_name: TableNameColumn({
            label: 'Table',
            mandatory: true,
        }),
        conditions: ConditionsColumn({
            label: 'Conditions',
            mandatory: true,
        }),
        sort_type: ChoiceColumn({
            label: 'Sort Type',
            maxLength: 32,
            default: 'sort_asc',
            choices: {
                sort_desc: {
                    label: 'z to a',
                    sequence: 1,
                },
                sort_asc: {
                    label: 'a to z',
                },
            },
        }),
        field_values: TemplateValueColumn({
            label: 'Fields',
            mandatory: true,
            maxLength: 65000,
            dependent: 'table_name',
        }),
        sort_column: FieldNameColumn({
            label: 'Order by',
        }),
        __snc_dont_fail_on_error: BooleanColumn({
            label: "Don't fail on error",
        }),
    },
    outputs: {
        count: IntegerColumn({
            label: 'Count',
        }),
        message: StringColumn({
            label: 'Error Message',
            maxLength: 10000,
        }),
        status: ChoiceColumn({
            label: 'Status',
            maxLength: 32,
            default: '1',
            choices: {
                0: {
                    label: 'Success',
                },
                1: {
                    label: 'Error',
                    sequence: 1,
                },
            },
        }),
    },
})
